package piglatin

import "strings"

func isVowel(r rune) bool {
	switch r {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func translateWord(word string) string {
	if word == "" {
		return ""
	}
	if isVowel(rune(word[0])) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}
	i := 0
	for i < len(word) {
		c := word[i]
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			i += 2
			break
		}
		if c == 'y' && i > 0 {
			break
		}
		if isVowel(rune(c)) {
			break
		}
		i++
	}
	return word[i:] + word[:i] + "ay"
}

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = translateWord(w)
	}
	return strings.Join(words, " ")
}
```

Wait — the loop: for "yellow": i=0, c='y', i>0 is false, not a vowel, so i=1. c='e' is a vowel → break. i=1. Result: "ellow" + "y" + "ay" = "ellowyay" ✓.

For "rhythm": i=0 'r' → i=1; 'h' → i=2; 'y' with i>0 → break. i=2. "ythm" + "rh" + "ay" = "ythmrhay" ✓.

For "my": i=0 'm' → i=1; 'y' with i>0 → break. "y" + "m" + "ay" = "ymay" ✓.

For "qat": i=0 'q', next is 'a' which is not u; not y; not a vowel → i=1; 'a' is a vowel → break. "at" + "q" + "ay" = "atqay" ✓.

For "queen": i=0 'q', next is 'u' → i=2, break. "een" + "qu" + "ay" = "eenquay" ✓.

For "square": i=0 's' → i=1; 'q' with next 'u' → i=3, break. "are" + "squ" + "ay" = "aresquay" ✓.

For "equal": starts with vowel → "equalay" ✓.

For "xenon": i=0 'x' → i=1; 'e' is a vowel → break. "enonxay" ✓.

For "koala": i=0 'k' → i=1; 'o' → break. "oalakay" ✓.

For "therapy": i=0 't' → 1; 'h' → 2; 'e' → break. "erapythay" ✓.

Edge case: what about a word that is all consonants, like "rhythm"? No problem. If the word is only consonants, e.g. "rth"? In that case i advances to len(word), and word[i:] = "", word[:i] = the whole word, and it becomes "word" + "ay". No problem.

Also, "xr" and "yt" are checked before the consonant loop — "xray" starts with 'x' which is a consonant, but the prefix check catches it. Good.

Note: The spec says Rule 1 checks for the "xr" or "yt" prefix. My implementation is fine.

